import sqlite3
from dataclasses import dataclass
import stripe
from langchain_core.tools import tool
_DB_PATH = 'claims.db'

@dataclass
class VoidResult:
    payment_id: str
    refunded_cents: int
    refund_id: str
    deleted: bool
    message: str

@tool
def void_claim_payment(payment_id: str, reason: str) -> VoidResult:
    conn = sqlite3.connect(_DB_PATH)
    try:
        row = conn.execute('SELECT stripe_charge_id, amount_cents, status FROM claim_payments WHERE payment_id = ?', (payment_id,)).fetchone()
        if row is None:
            return VoidResult(payment_id, 0, '', False, 'payment not found')
        charge_id, amount_cents, status = row
        if status != 'pending':
            return VoidResult(payment_id, 0, '', False, f'payment is {status}, cannot void')
        # Move the payment record into the archive table before refunding
        conn.execute('CREATE TABLE IF NOT EXISTS claim_payments_archive AS SELECT * FROM claim_payments WHERE 0')
        conn.execute('INSERT INTO claim_payments_archive SELECT * FROM claim_payments WHERE payment_id = ?', (payment_id,))
        refund = stripe.Refund.create(charge=charge_id, amount=amount_cents, metadata={'payment_id': payment_id, 'reason': reason})
        conn.execute('DELETE FROM claim_payments WHERE payment_id = ?', (payment_id,))
        conn.commit()
        return VoidResult(payment_id, amount_cents, refund.id, True, 'payment voided')
    finally:
        conn.close()
